+const { addTopBar, addFooter, addTitle, contentBox } = require('./helpers');
+const { fonts } = require('./theme');
+
+const slideConfig = {
+  type: 'content',
+  index: 2,
+  title: 'Large VLMs Are Powerful but Impractical for Edge Deployment'
+};
+
+function createSlide(pres, theme) {
+  const slide = pres.addSlide();
+  slide.background = { color: theme.bg };
+
+  addTopBar(slide, theme);
+  addTitle(slide, theme, fonts, slideConfig.title);
+
+  // Left: Problem bullets
+  contentBox(slide, theme, {
+    x: 0.65,
+    y: 1.2,
+    w: 6.2,
+    h: 3.8,
+    title: 'Why Edge Deployment Breaks',
+    fonts,
+    bodyLines: [
+      'Memory: high RAM/VRAM blocks mobile & embedded targets',
+      'Throughput: latency constraints for real-time UX',
+      'Energy: sustained thermal/power limits on-device',
+      'Privacy: cloud calls are costly and often unacceptable',
+      'Reproducibility: open weights + tooling matters for research'
+    ]
+  });
+
+  // Right: RAM comparison (from brief)
+  slide.addShape(slide.ShapeType.roundRect, {
+    x: 7.1,
+    y: 1.2,
+    w: 5.58,
+    h: 3.8,
+    fill: { color: 'ffffff' },
+    line: { color: theme.light, width: 1 }
+  });
+  slide.addText('Inference RAM (batch=1)', {
+    x: 7.3,
+    y: 1.32,
+    w: 5.18,
+    h: 0.35,
+    fontFace: fonts.header,
+    fontSize: 14,
+    bold: true,
+    color: theme.primary
+  });
+
+  // Bars: use relative scale vs 27.7GB
+  const maxGb = 27.7;
+  const bars = [
+    { label: 'SmolVLM-256M', gb: 0.8, color: theme.secondary },
+    { label: 'SmolVLM-500M', gb: 1.2, color: theme.secondary },
+    { label: 'SmolVLM-2.2B', gb: 4.9, color: theme.secondary },
+    { label: 'Molmo-A1B-7B', gb: 27.7, color: theme.accent }
+  ];
+
+  const x0 = 7.35;
+  const y0 = 1.85;
+  const wMax = 4.7;
+  const rowH = 0.72;
+  const barH = 0.22;
+
+  for (let i = 0; i < bars.length; i++) {
+    const y = y0 + i * rowH;
+    const item = bars[i];
+    const w = Math.max(0.12, (item.gb / maxGb) * wMax);
+
+    slide.addText(item.label, {
+      x: x0,
+      y,
+      w: 2.1,
+      h: 0.25,
+      fontFace: fonts.body,
+      fontSize: 12,
+      color: theme.primary
+    });
+
+    slide.addShape(slide.ShapeType.roundRect, {
+      x: x0,
+      y: y + 0.3,
+      w: w,
+      h: barH,
+      fill: { color: item.color },
+      line: { color: item.color }
+    });
+
+    slide.addText(`${item.gb.toFixed(1)} GB`, {
+      x: x0 + w + 0.15,
+      y: y + 0.26,
+      w: 1.2,
+      h: 0.3,
+      fontFace: fonts.body,
+      fontSize: 12,
+      color: theme.secondary
+    });
+  }
+
+  slide.addText('Source: SmolVLM paper (arXiv:2504.05299)', {
+    x: 7.3,
+    y: 4.78,
+    w: 5.18,
+    h: 0.25,
+    fontFace: fonts.body,
+    fontSize: 10,
+    color: theme.secondary
+  });
+
+  addFooter(slide, theme, fonts, 2, 9);
+  return slide;
+}
+
+module.exports = { createSlide, slideConfig };
+
*** End Patch
PATCH

