+const { addTopBar, addFooter, addTitle, addSubtitle } = require('./helpers');
+const { fonts } = require('./theme');
+
+const slideConfig = {
+  type: 'content',
+  index: 3,
+  title: 'SmolVLM Architecture: Image Splitting, Pixel Shuffle, and SmolLM2 Backbone'
+};
+
+function createSlide(pres, theme) {
+  const slide = pres.addSlide();
+  slide.background = { color: theme.bg };
+
+  addTopBar(slide, theme);
+  addTitle(slide, theme, fonts, slideConfig.title);
+  addSubtitle(slide, theme, fonts, 'Pipeline: split images  vision encode  pixel shuffle compress  project  concatenate with text  SmolLM2');
+
+  // Figure: architecture
+  slide.addShape(slide.ShapeType.roundRect, {
+    x: 0.65,
+    y: 1.55,
+    w: 8.1,
+    h: 3.95,
+    fill: { color: 'ffffff' },
+    line: { color: theme.light, width: 1 }
+  });
+  slide.addImage({
+    path: `${__dirname}/imgs/figure_3.jpg`,
+    x: 0.85,
+    y: 1.72,
+    w: 7.7,
+    h: 3.55
+  });
+
+  // Right: key steps
+  slide.addShape(slide.ShapeType.roundRect, {
+    x: 8.95,
+    y: 1.55,
+    w: 4.38,
+    h: 3.95,
+    fill: { color: theme.primary },
+    line: { color: theme.primary }
+  });
+  slide.addText('Flow (paper)', {
+    x: 9.18,
+    y: 1.7,
+    w: 3.9,
+    h: 0.35,
+    fontFace: fonts.header,
+    fontSize: 14,
+    bold: true,
+    color: theme.bg
+  });
+
+  const bullets = [
+    'Split image into sub-images',
+    'Encode with SigLIP vision encoder',
