const { addTopBar, addFooter, addTitle, contentBox } = require('./helpers');
const { fonts } = require('./theme');

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'Smaller Vision Encoders Outperform Larger Ones in Compact VLMs'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  addTopBar(slide, theme);
  addTitle(slide, theme, fonts, slideConfig.title);

  // Left: finding text (no extra fabricated numbers)
  contentBox(slide, theme, {
    x: 0.65,
    y: 1.2,
    w: 5.95,
    h: 3.1,
    title: 'Finding 1: Balanced EncoderLM Compute',
    fonts,
    bodyLines: [
      'For small LMs, oversized vision encoders can waste parameters',
      '93M SigLIP-B/16 + 135M LM outperforms 428M SigLIP-SO400M + same LM',
      'Only at 1.7B LM scale does the larger encoder pay off (~10% overhead)'
    ]
  });

  // Right: comparison bars (visual only; no fabricated metric)
  slide.addShape(slide.ShapeType.roundRect, {
    x: 6.95,
    y: 1.2,
    w: 6.38,
    h: 3.1,
    fill: { color: 'ffffff' },
    line: { color: theme.light, width: 1 }
  });
  slide.addText('Small-LM Regime (135M LM): Encoder Choice', {
    x: 7.15,
    y: 1.32,
    w: 5.98,
    h: 0.35,
    fontFace: fonts.header,
    fontSize: 14,
    bold: true,
    color: theme.primary
  });

  // Two horizontal bars representing encoder parameter size
  const baseX = 7.15;
  const barX = 7.15;
  const barY1 = 2.05;
  const barY2 = 2.85;
  const barWMax = 5.8;
  const maxParams = 428;

  const encoders = [
    {
      name: 'SigLIP-B/16',
      paramsM: 93,
      color: theme.secondary,
      tag: 'better for smallest LMs'
    },
    {
      name: 'SigLIP-SO400M',
      paramsM: 428,
      color: theme.light,
      tag: 'over-allocates compute'
    }
  ];

  function drawEncoderRow(y, enc) {
    slide.addText(enc.name, {
      x: baseX,
      y: y - 0.28,
      w: 2.2,
      h: 0.25,
      fontFace: fonts.body,
      fontSize: 12,
      color: theme.primary
    });
    slide.addText(`${enc.paramsM}M params`, {
      x: baseX + 2.2,
      y: y - 0.28,
      w: 1.6,
      h: 0.25,
      fontFace: fonts.body,
      fontSize: 12,
      color: theme.secondary
    });
    const w = Math.max(0.3, (enc.paramsM / maxParams) * barWMax);
    slide.addShape(slide.ShapeType.roundRect, {
      x: barX,
      y,
      w,
      h: 0.3,
      fill: { color: enc.color },
      line: { color: enc.color }
    });
    slide.addText(enc.tag, {
      x: barX + w + 0.2,
      y: y + 0.03,
      w: 2.2,
      h: 0.25,
      fontFace: fonts.body,
      fontSize: 11,
      color: theme.secondary
    });
  }

  drawEncoderRow(barY1, encoders[0]);
  drawEncoderRow(barY2, encoders[1]);

  slide.addShape(slide.ShapeType.roundRect, {
    x: 0.65,
    y: 4.5,
    w: 12.68,
    h: 0.7,
    fill: { color: theme.primary },
    line: { color: theme.primary }
  });
  slide.addText('Design implication: for compact VLMs, allocate capacity where it pays off  avoid over-sizing the vision encoder when the LM is small.', {
    x: 0.85,
    y: 4.66,
    w: 12.28,
    h: 0.45,
    fontFace: fonts.body,
    fontSize: 14,
    color: theme.bg
  });

  addFooter(slide, theme, fonts, 4, 9);
  return slide;
}

module.exports = { createSlide, slideConfig };

